import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { type TableColumnsType, Typography } from 'antd';

import { BalanceTransactionRead, useReportsBalanceTransactionsListQuery } from 'entities/Report';
import { getUrlParamsForApi } from 'features/Filters';
import { useMedia } from 'shared/hooks';
import { formatDate, getDefaultSortOrder, getStringQueryParamsForExport } from 'shared/utils';

export const useRawReportsList = () => {
	const { t } = useTranslation();
	const isDesktop = useMedia('desktop');
	const [searchParams] = useSearchParams();
	const exportURL = `/api/reports/balance_transactions/export?${getStringQueryParamsForExport(searchParams)}}`;

	const columns: TableColumnsType<BalanceTransactionRead> = [
		{
			title: t('Offer name'),
			dataIndex: 'offer',
			key: 'offer',
			sorter: true,
			defaultSortOrder: getDefaultSortOrder(searchParams, 'offer'),
			render: (_: string, record: BalanceTransactionRead) => (
				<Typography.Text strong>{record.offer?.name}</Typography.Text>
			),
		},
		{
			title: t('Amount'),
			dataIndex: 'amount',
			key: 'amount',
			sorter: true,
			defaultSortOrder: getDefaultSortOrder(searchParams, 'amount'),
			align: 'right',
			render: (_: string, record: BalanceTransactionRead) => (
				<>
					{record.amount} {record.currency}
				</>
			),
		},
		{
			title: t('Status'),
			dataIndex: 'reason',
			key: 'reason',
			render: (reason: string) => (
				<Typography.Text style={{ maxWidth: 200 }} ellipsis={{ tooltip: reason }}>
					{reason}
				</Typography.Text>
			),
		},
		{
			title: t('Date and Time'),
			dataIndex: 'created_at',
			key: 'created_at',
			sorter: true,
			defaultSortOrder: getDefaultSortOrder(searchParams, 'created_at'),
			render: (created_at: string) => (
				<Typography.Text type="secondary">{formatDate(new Date(created_at), 'long')}</Typography.Text>
			),
		},
	];

	const { data, isFetching, isLoading, isError } = useReportsBalanceTransactionsListQuery(
		getUrlParamsForApi(searchParams),
	);

	return {
		columns,
		data,
		exportURL,
		isDesktop,
		isError,
		isFetching,
		isLoading,
		t,
	};
};
