import { FC, HTMLAttributes } from 'react';

import { Typography } from 'antd';
import cn from 'classnames';

import noImageIcon from 'assets/images/no-image.svg';

import styles from './ReportOffer.module.scss';

interface IReportOfferProps extends HTMLAttributes<HTMLDivElement> {
	image: string | null | undefined;
	name: string;
}

export const ReportOffer: FC<IReportOfferProps> = ({ className, image, name, ...props }) => {
	return (
		<div {...props} className={cn(className, styles.reportOffer)}>
			<img src={image || noImageIcon} alt={name} width={36} height={36} />
			<Typography.Text>{name}</Typography.Text>
		</div>
	);
};
