import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { type TableColumnsType, Typography } from 'antd';

import {
	ReportOffer,
	SourceMonthlyCapRead,
	SourceMonthlyCapStatusEnum,
	useReportsSourceMonthlyCapsListQuery,
} from 'entities/Report';
import { getUrlParamsForApi } from 'features/Filters';
import { useMedia } from 'shared/hooks';
import { getDefaultSortOrder, getStringQueryParamsForExport } from 'shared/utils';

export const useCapReportsList = () => {
	const { t } = useTranslation();
	const isDesktop = useMedia('desktop');
	const [searchParams] = useSearchParams();
	const exportURL = `/api/reports/source_monthly_caps/export?${getStringQueryParamsForExport(searchParams)}}`;

	const columns: TableColumnsType<SourceMonthlyCapRead> = [
		{
			title: t('Offer name'),
			dataIndex: 'offer',
			key: 'offer',
			sorter: true,
			defaultSortOrder: getDefaultSortOrder(searchParams, 'offer'),
			render: (_: string, record: SourceMonthlyCapRead) => (
				<ReportOffer image={record.offer?.image} name={record.offer?.name} />
			),
		},
		{
			title: t('Source ID'),
			dataIndex: 'source_id',
			key: 'source_id',
			render: (source_id: string) => (
				<Typography.Text style={{ maxWidth: 200 }} ellipsis={{ tooltip: source_id }}>
					{source_id}
				</Typography.Text>
			),
		},
		{
			title: t('Status'),
			dataIndex: 'status',
			key: 'status',
			render: (status: SourceMonthlyCapStatusEnum | null) => (
				<Typography.Text type="secondary">{status}</Typography.Text>
			),
		},
	];

	const { data, isFetching, isLoading, isError } = useReportsSourceMonthlyCapsListQuery(
		getUrlParamsForApi(searchParams),
	);

	return {
		columns,
		data,
		exportURL,
		isDesktop,
		isError,
		isFetching,
		isLoading,
		t,
	};
};
