import { ETableSearchParams } from 'shared/typings';

import { camelCaseToSnakeCase } from './camelCaseToSnakeCase';

export const getStringQueryParamsForExport = (searchParams: URLSearchParams) => {
	const newParams = new URLSearchParams({});
	const excludeParams: string[] = [ETableSearchParams.LIMIT, ETableSearchParams.OFFSET];
	searchParams.forEach((value, key) => {
		if (excludeParams.includes(key)) return;
		const name = camelCaseToSnakeCase(key);
		newParams.append(name, value);
	});
	return newParams.toString();
};
